import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.Dp3tugkT.js";const m=JSON.parse('{"title":"Tech Choice Comparisons","description":"","frontmatter":{},"headers":[],"relativePath":"04-tech-comparisons.md","filePath":"04-tech-comparisons.md"}'),n={name:"04-tech-comparisons.md"};function d(s,t,i,c,h,l){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="tech-choice-comparisons" tabindex="-1">Tech Choice Comparisons <a class="header-anchor" href="#tech-choice-comparisons" aria-label="Permalink to &quot;Tech Choice Comparisons&quot;">​</a></h1><h2 id="_1-short-slug-generation-nanoid-vs-md5-hash-truncation-vs-base62-auto-increment-vs-uuidv4" tabindex="-1">1. Short Slug Generation: Nanoid vs MD5 Hash Truncation vs Base62 Auto-Increment vs UUIDv4 <a class="header-anchor" href="#_1-short-slug-generation-nanoid-vs-md5-hash-truncation-vs-base62-auto-increment-vs-uuidv4" aria-label="Permalink to &quot;1. Short Slug Generation: Nanoid vs MD5 Hash Truncation vs Base62 Auto-Increment vs UUIDv4&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Criteria</th><th>Nanoid (Chosen)</th><th>MD5 / SHA-256 Truncation</th><th>Base62 Auto-Increment</th><th>UUIDv4</th></tr></thead><tbody><tr><td>Slug Length</td><td>7 characters</td><td>7-8 characters</td><td>Variable (1 to 6 chars)</td><td>36 characters (Too long)</td></tr><tr><td>Collision Risk</td><td>Negligible ($64^7$ space)</td><td>High after truncation</td><td>Zero (Monotonic ID)</td><td>Zero</td></tr><tr><td>Information Leakage</td><td>None (cryptographically random)</td><td>None</td><td>High (Competitor counts)</td><td>None</td></tr><tr><td>Coordination Overhead</td><td>Zero (Distributed)</td><td>Zero</td><td>Requires centralized sequence</td><td>Zero</td></tr></tbody></table><p><strong>Why Chosen</strong>: Nanoid provides collision resistance, zero coordination overhead, and complete privacy without exposing total business volume through sequential IDs.</p><h2 id="_2-redirection-status-http-302-found-vs-http-301-moved-permanently" tabindex="-1">2. Redirection Status: HTTP 302 Found vs HTTP 301 Moved Permanently <a class="header-anchor" href="#_2-redirection-status-http-302-found-vs-http-301-moved-permanently" aria-label="Permalink to &quot;2. Redirection Status: HTTP 302 Found vs HTTP 301 Moved Permanently&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Criteria</th><th>HTTP 302 (Chosen)</th><th>HTTP 301</th></tr></thead><tbody><tr><td>Browser Caching</td><td>No caching (requests hit server every time)</td><td>Cached aggressively by browser</td></tr><tr><td>Analytics Accuracy</td><td>100% accurate per-click tracking</td><td>Drops drastically after first visit</td></tr><tr><td>Server Load</td><td>Handles every click event</td><td>Zero load on repeated clicks</td></tr></tbody></table><p><strong>Why Chosen</strong>: URL shorteners rely heavily on accurate telemetry and analytics for creators; HTTP 301 completely undermines this capability.</p>',7)])])}const p=e(n,[["render",d]]);export{m as __pageData,p as default};
